/* From Uiverse.io by misaraadel - Tags: switch, theme-switch, toggle switch, on/off, 3d switch, cool switch, creative switch */
.__UIV_SCOPE__ .switch {
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .switch input {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  opacity: 0;
  position: relative;
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  z-index: 99;
  cursor: pointer;
}

.__UIV_SCOPE__ .switch input:checked ~ .check {
  background-color: #549b60;
}

.__UIV_SCOPE__ .switch input:checked ~ .check::after {
  transform: translateX(0px);
}

.__UIV_SCOPE__ .switch input:checked ~ .check::before {
  transform: translateX(50px) !important;
}

.__UIV_SCOPE__ .switch .check {
  width: 51px;
  height: 30px;
  position: relative;
  display: block;
  background-color: #E92E2E;
  cursor: pointer;
  border-radius: 15px;
  overflow: hidden;
  transition: all 0.5s ease-in;
}

.__UIV_SCOPE__ .switch .check::after,
.__UIV_SCOPE__ .switch .check::before {
  content: "";
  position: absolute;
  top: 0;
  width: 30px;
  height: 30px;
  transition: all 0.5s ease-in;
  border-radius: 50%;
}

.__UIV_SCOPE__ .switch .check::before {
  background-color: #fff;
  right: 0px;
}

.__UIV_SCOPE__ .switch .check::after {
  transform: translateX(-60px);
  background-color: #fff;
  left: 0;
}
